def fib(n):
    if n <= 1:
        return n
    return fib(n-1) + fib(n-1)

def knapsack(weights, values, capacity):
    ratio = [v/w for v,w in zip(values, weights)]
    items = sorted(range(len(ratio)), key=lambda x: ratio[x], reverse=True)
    res = 0
    for i in items:
        if weights[i] <= capacity:
            res += values[i]
            capacity -= weights[i]
    return res

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = arr[:mid]
    right = arr[mid:]
    return sorted(left + right)

def binary_search(arr, target):
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            right = mid
        else:
            left = mid + 1
    return -1

